
export  default {
    data(){
      return{
        products:[],   
      }
    },
 
    methods:{
        getProducts(){
            const vm = this;
    
            const api = `${process.env.VUE_APP_API}/api/${process.env.VUE_APP_PATH}/products/all`;
            console.log(api);
            vm.isLoading=true;
            this.$http.get(api).then((res)=>{               
                if(res.data.success){
                    vm.products = res.data.products;
                    vm.isLoading=false;
                    console.log(vm.products);
                  
                }
                else{
                    alert("尚未得到");
                }
            })
        }
    }
 
 }
 
 
 